import fs from "node:fs";
import path from "node:path";

const OUTPUT_PATH = path.resolve(
  import.meta.dirname,
  "../../src/lib/design/pencil-tokens.ts",
);

export function writePencilTokensTs(tokenDocument) {
  const lightEntries = Object.entries(tokenDocument.variables).filter(
    ([, entry]) => entry.light != null && entry.css,
  );

  const lightColors = {};
  for (const [key, entry] of lightEntries) {
    const suffix = key.replace("color.apple.", "");
    lightColors[suffix] = entry.light;
  }

  const content = `/**
 * AUTO-GENERATED by scripts/sync-design-tokens.mjs — do not edit by hand.
 * Source: design/tokens.json
 * Run: npm run sync:design
 */
export const PENCIL_APPLE_CSS_VARS = {
  bg: "--apple-bg",
  surface: "--apple-surface",
  text: "--apple-text",
  textSecondary: "--apple-text-secondary",
  link: "--apple-link",
  separator: "--apple-separator",
  cardBg: "--apple-card-bg",
  navBg: "--apple-nav-bg",
} as const;

export const PENCIL_APPLE_LIGHT_COLORS = ${JSON.stringify(lightColors, null, 2)} as const;

export const PENCIL_LAYOUT_SIZES = {
  gridUnit: ${tokenDocument.variables["spacing.gridUnit"].value},
  insetGroupRadius: ${tokenDocument.variables["radius.insetGroup"].value},
  sheetRadius: ${tokenDocument.variables["radius.sheet"].value},
  touchMinHeight: ${tokenDocument.variables["size.touchMin"].value},
  listRowMinHeight: ${tokenDocument.variables["size.listRowMin"].value},
  headerHeight: ${tokenDocument.variables["size.header"].value},
  tabBarHeight: ${tokenDocument.variables["size.tabBar"].value},
  contentMaxWidth: ${tokenDocument.variables["size.contentMaxWidth"].value},
} as const;

export const PENCIL_PEN_FILES = {
  dashboard: "design/screens/dashboard.pen",
  groups: "design/screens/groups.pen",
  groupDetail: "design/screens/group-detail.pen",
  settings: "design/screens/settings.pen",
  login: "design/screens/login.pen",
  landing: "design/screens/landing.pen",
  tokensJson: "design/tokens.json",
} as const;
`;

  fs.mkdirSync(path.dirname(OUTPUT_PATH), { recursive: true });
  fs.writeFileSync(OUTPUT_PATH, content);
}
